WITH nr AS (
    SELECT SUM(third_party_billed_gross - rebate_accrual - deferred_unearned + prior_period_release) AS net_rev
    FROM north.ledger.monthly_pack
    WHERE EXTRACT(year FROM period_end) = 2025
)
SELECT net_rev AS answer FROM nr;

WITH north_rent AS (
  SELECT SUM(property_rent) AS total_rent
  FROM north.ledger.monthly_pack
  WHERE period_end >= DATE '2025-01-31' AND period_end <= DATE '2025-12-31'
)
SELECT total_rent AS answer FROM north_rent;

WITH west_entity AS (
  SELECT entity_code FROM holdco.ref.entity WHERE legal_name = 'Madeup West Assemblies Inc'
),
 decl AS (
  SELECT SUM(pa.rejected_addback_functional) AS total_declined
  FROM holdco.ref.policy_adjustment pa
  JOIN west_entity we ON pa.entity_code = we.entity_code
  WHERE pa.period_end >= DATE '2025-01-31' AND pa.period_end <= DATE '2025-12-31'
)
SELECT total_declined AS answer FROM decl;
